import{_ as e,c as a,o as l,ai as r}from"./chunks/framework.BHQ3CDIQ.js";const i="/Scientific-Programming-in-Julia/dev/assets/dual.Bfkd36-y.png",u=JSON.parse('{"title":"","description":"","frontmatter":{"layout":"home","hero":{"name":"","text":"Scientific Programming in Julia","image":{"light":"/logo.svg","dark":"/logo-dark.svg"},"outline":true,"actions":[{"theme":"brand","text":"Lectures","link":"/lectures/outline"},{"theme":"alt","text":"Tutorials","link":"/tutorials/installation"},{"theme":"alt","text":"Projects","link":"/projects/requirements"}]}},"headers":[],"relativePath":"index.md","filePath":"index.md","lastUpdated":null}'),o={name:"index.md"};function n(s,t,h,d,c,f){return l(),a("div",null,[...t[0]||(t[0]=[r('<p>Scientific Programming requires the highest performance but we also want to write very high level code to enable rapid prototyping and avoid error prone, low level implementations.</p><p>The <a href="https://docs.julialang.org/en/v1/" target="_blank" rel="noreferrer">Julia</a> programming language is designed with exactly those requirements of scientific computing in mind. In this course we will show you how to make use of the tools and advantages that <em>jit-compiled</em> Julia provides over <em>dynamic</em>, high-level languages like Python or lower level languages like C++.</p><p><img src="'+i+'" alt=""></p><p>Before joining the course, consider reading the following two blog posts to figure out if Julia is a language in which you want to invest your time.</p><ul><li><p>What is <a href="https://viralinstruction.com/posts/goodjulia/" target="_blank" rel="noreferrer"><em>great</em></a> about Julia.</p></li><li><p>What is <a href="https://viralinstruction.com/posts/badjulia/" target="_blank" rel="noreferrer"><em>bad</em></a> about Julia.</p></li></ul><h2 id="What-will-you-learn?" tabindex="-1">What will you learn? <a class="header-anchor" href="#What-will-you-learn?" aria-label="Permalink to &quot;What will you learn? {#What-will-you-learn?}&quot;">​</a></h2><p>First and foremost you will learn how to <em><strong>think julia</strong></em> - meaning how write fast, extensible, reusable, and easy-to-read code using things like <em>optional typing</em>, <em>multiple dispatch</em>, and functional programming concepts. The later part of the course will teach you how to use more advanced concepts like <em>language introspection</em>, <em>metaprogramming</em>, and <em>symbolic computing</em>. Amonst others you will <em><strong>implement your own automatic differentiation</strong></em> (the backbone of modern machine learning) package based on these advanced techniques that can transform intermediate representations of Julia code.</p><h2 id="Organization" tabindex="-1">Organization <a class="header-anchor" href="#Organization" aria-label="Permalink to &quot;Organization {#Organization}&quot;">​</a></h2><p>This course webpage contains all information about the course that you need, including lecture notes, lab instructions, and homeworks. The official format of the course is 2+2 (2h lectures/2h labs per week) for 4 credits.</p><p>The official course code is: <strong>B0M36SPJ</strong> and the timetable for the winter semester 2022 can be found <a href="https://fel.cvut.cz/cz/education/rozvrhy-ng.B221/public/html/predmety/69/85/p6985906.html" target="_blank" rel="noreferrer">here</a>.</p><p>The course will be graded based on points from your homework (<strong>max. 20 points</strong>) and points from a <a href="/Scientific-Programming-in-Julia/dev/index#final_project">final project</a> (<strong>max. 30 points</strong>).</p><p>Below is a table that shows which lectures have homeworks (and their points).</p><table tabindex="0"><thead><tr><th style="text-align:left;">Homework</th><th style="text-align:left;">1</th><th style="text-align:left;">2</th><th style="text-align:left;">3</th><th style="text-align:left;">4</th><th style="text-align:left;">5</th><th style="text-align:left;">6</th><th style="text-align:left;">7</th><th style="text-align:left;">8</th><th style="text-align:left;">9</th><th style="text-align:left;">10</th><th style="text-align:left;">11</th><th style="text-align:left;">12</th><th style="text-align:left;">13</th></tr></thead><tbody><tr><td style="text-align:left;">Points</td><td style="text-align:left;">2</td><td style="text-align:left;">2</td><td style="text-align:left;">2</td><td style="text-align:left;">2</td><td style="text-align:left;">2</td><td style="text-align:left;">2</td><td style="text-align:left;">2</td><td style="text-align:left;">2</td><td style="text-align:left;">-</td><td style="text-align:left;">2</td><td style="text-align:left;">-</td><td style="text-align:left;">2</td><td style="text-align:left;">-</td></tr></tbody></table><p>Hint: The <strong>first few homeworks are easier</strong>. Use them to fill up your points.</p><h2 id="final_project" tabindex="-1">Final project <a class="header-anchor" href="#final_project" aria-label="Permalink to &quot;Final project {#final_project}&quot;">​</a></h2><p>The final project will be individually agreed on for each student. Ideally you can use this project to solve a problem you have e.g. in your thesis, but don&#39;t worry - if you cannot come up with an own project idea, we will suggest one to you. More info and project suggestion can be found <a href="/Scientific-Programming-in-Julia/dev/projects/requirements#projects">here</a>. Check out the <a href="/Scientific-Programming-in-Julia/dev/projects/projects#former_projects">list of projects</a> from past to get a feeling for what we expect.</p><h2 id="Grading" tabindex="-1">Grading <a class="header-anchor" href="#Grading" aria-label="Permalink to &quot;Grading {#Grading}&quot;">​</a></h2><p>Your points from the homeworks and the final project are summed and graded by the standard grading scale below.</p><table tabindex="0"><thead><tr><th style="text-align:left;">Grade</th><th style="text-align:left;">A</th><th style="text-align:left;">B</th><th style="text-align:left;">C</th><th style="text-align:left;">D</th><th style="text-align:left;">E</th><th style="text-align:left;">F</th></tr></thead><tbody><tr><td style="text-align:left;">Points</td><td style="text-align:left;">45-50</td><td style="text-align:left;">40-44</td><td style="text-align:left;">35-39</td><td style="text-align:left;">30-34</td><td style="text-align:left;">25-29</td><td style="text-align:left;">0-25</td></tr></tbody></table><h2 id="emails" tabindex="-1">Teachers <a class="header-anchor" href="#emails" aria-label="Permalink to &quot;Teachers {#emails}&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">–</th><th style="text-align:left;">E-mail</th><th style="text-align:left;">Room</th><th style="text-align:left;">Role</th></tr></thead><tbody><tr><td style="text-align:left;">Tomáš Pevný</td><td style="text-align:left;"><a href="mailto:pevnak@protonmail.ch" target="_blank" rel="noreferrer">pevnak@protonmail.ch</a></td><td style="text-align:left;">KN:E-406</td><td style="text-align:left;">Lecturer</td></tr><tr><td style="text-align:left;">Vašek Šmídl</td><td style="text-align:left;"><a href="mailto:smidlva1@fjfi.cvut.cz" target="_blank" rel="noreferrer">smidlva1@fjfi.cvut.cz</a></td><td style="text-align:left;">KN:E-333</td><td style="text-align:left;">Lecturer</td></tr><tr><td style="text-align:left;">Matěj Zorek</td><td style="text-align:left;"><a href="mailto:zorekmat@fel.cvut.cz" target="_blank" rel="noreferrer">zorekmat@fel.cvut.cz</a></td><td style="text-align:left;">KN:E-333</td><td style="text-align:left;">Lab Instructor</td></tr><tr><td style="text-align:left;">Niklas Heim</td><td style="text-align:left;"><a href="mailto:heimnikl@fel.cvut.cz" target="_blank" rel="noreferrer">heimnikl@fel.cvut.cz</a></td><td style="text-align:left;">KN:E-333</td><td style="text-align:left;">Lab Instructor</td></tr></tbody></table><h2 id="Prerequisites" tabindex="-1">Prerequisites <a class="header-anchor" href="#Prerequisites" aria-label="Permalink to &quot;Prerequisites {#Prerequisites}&quot;">​</a></h2><p>There are no hard requirements to take the course. We go through the basics of Julia, but we do it rather quickly, so some familiarity with the language is an advantage. If you are looking for an in depth course on the basics of the language, we recommend to check out <a href="https://github.com/JuliaTeachingCTU/Julia-for-Optimization-and-Learning" target="_blank" rel="noreferrer">Julia for Optimization and Learning</a> before enrolling in this course. The <a href="https://cw.fel.cvut.cz/b202/courses/fup/start" target="_blank" rel="noreferrer">Functional Programming</a> course also contains some helpful concepts for this course. And knowledge about computer hardware, namely basics of how CPU works, how it interacts with memory through caches, and basics of multi-threading certainly helps.</p><h2 id="References" tabindex="-1">References <a class="header-anchor" href="#References" aria-label="Permalink to &quot;References {#References}&quot;">​</a></h2><ul><li><p><a href="https://docs.julialang.org/en/v1/" target="_blank" rel="noreferrer">Official documentation</a></p></li><li><p><a href="https://modernjuliaworkflows.github.io" target="_blank" rel="noreferrer">Modern Julia Workflows</a></p></li><li><p><a href="https://www.youtube.com/watch?v=qM9NtiYlXck" target="_blank" rel="noreferrer">Workflow tips, and what is new in v1.9</a></p></li><li><p><a href="https://github.com/Datseris/Zero2Hero-JuliaWorkshop" target="_blank" rel="noreferrer">Zero2Hero Julia Workhop</a></p></li><li><p><a href="https://benlauwens.github.io/ThinkJulia.jl/latest/book.html#chap01" target="_blank" rel="noreferrer">Think Julia: How to Think Like a Computer Scientist</a></p></li><li><p><a href="https://techytok.com/from-zero-to-julia/" target="_blank" rel="noreferrer">From Zero to Julia!</a></p></li><li><p><a href="https://en.wikibooks.org/wiki/Introducing_Julia" target="_blank" rel="noreferrer">WikiBooks</a></p></li><li><p><a href="https://jkrumbiegel.com/pages/2022-08-26-pkg-introduction/" target="_blank" rel="noreferrer">Justin Krumbiel&#39;s</a> excellent introduction to the package manager.</p></li><li><p><a href="https://juliadatascience.io" target="_blank" rel="noreferrer">juliadatascience.io</a> contains an excellent introduction to plotting with Makie.</p></li><li><p>The art of <a href="https://scientificcoder.com/the-art-of-multiple-dispatch" target="_blank" rel="noreferrer">multiple dispatch</a></p></li><li><p>MIT Course: <a href="https://github.com/mitmath/JuliaComputation" target="_blank" rel="noreferrer">Julia Computation</a></p></li><li><p>Tim Holy&#39;s <a href="https://github.com/timholy/AdvancedScientificComputing" target="_blank" rel="noreferrer">Advanced Scientific Computing</a></p></li></ul>',25)])])}const m=e(o,[["render",n]]);export{u as __pageData,m as default};
